-- Off-season programs (GRIZZ, 2026-10-23): 8-week programs for Soccer,
-- Rugby, American Football, Baseball, Basketball, Tennis, Enduro riding,
-- Cycling and Mountain Biking ("Soccer/Football" is the Soccer one).
--
-- Week layout (days 1-7 = Mon-Sun). Field and court sports: Mon Strength A
-- (lower body), Tue Conditioning, Wed Active recovery (zone 2 + mobility),
-- Thu Strength B (upper body & hips), Fri Speed & power, Sat play the sport
-- or rest, Sun full rest. Enduro swaps speed for power and core and adds
-- grip, neck and isometric leg work. Cycling and mountain biking: strength
-- Mon and Thu, an interval ride Tue, a recovery ride Wed, sprints Fri and a
-- long ride Sat.
--
-- Weeks 1-3 build (rows marked to grow gain a set in weeks 2 and 3, up to
-- 6), week 4 is a recovery week at half the sets, weeks 5-7 turn strength
-- into power and sport-specific fitness (contrast pairs, repeated sprints,
-- harder intervals), and week 8 is a test week at half the sets.
--
-- Based on the off-season S&C research: general strength first, then power;
-- hamstring (Nordic) and groin work against the common field-sport injuries;
-- rotator cuff and upper back work and no overhead pressing for throwing and
-- racket sports (and GRIZZ's rule for built-ins); neck work for contact
-- sports and riding; conditioning shaped to each sport's work-to-rest. Every
-- exercise is already in the library. A program that is already there is
-- updated in place, row by row; nothing is removed.
--
-- Review for gains and injury risk (GRIZZ, 2026-10-23): field and court
-- sports train every muscle twice a week (a row on Monday, hip thrusts on
-- Thursday); Nordics start at 2 sets and build, then 2 sets keep the
-- protection, so Tuesday's running isn't done on sore hamstrings; sprints are
-- at 9/10 in weeks 1-3 and the 4-minute intervals start at 3 rounds; repeated
-- sprint sets don't grow; depth jumps are from a low box; dead hangs stop
-- short of grip failure; no set goes to failure.

create or replace function public.add_offseason_program(p_name text, p_description text, p_nutrition text, p_warm_up text, p_titles jsonb, p_tpl jsonb)
returns void language plpgsql as $f$
declare
  prog uuid;
  titles text[] := '{}';
  w int;
  dd int;
  ph text;
  wp int;
  half boolean;
  tag text;
  d text;
  r jsonb;
  i int;
  n int;
begin
  for w in 1..8 loop
    tag := case w when 4 then ' (recovery week)' when 8 then ' (test week)' else '' end;
    for dd in 1..7 loop
      titles := titles || ((p_titles ->> dd::text) || case when p_tpl -> 'p1' ? dd::text then tag else '' end);
    end loop;
  end loop;
  select id into prog from public.programs where trainer_id is null and name = p_name limit 1;
  if prog is null then
    insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
    values (null, p_name, 'weekly', 'gym', 8, p_description, p_nutrition, p_warm_up, titles)
    returning id into prog;
  else
    update public.programs set description = p_description, nutrition = p_nutrition, warm_up = p_warm_up, day_titles = titles
    where id = prog;
  end if;
  for w in 1..8 loop
    ph := case when w <= 4 then 'p1' else 'p2' end;
    half := w in (4, 8);
    wp := case when w <= 3 then w when w between 5 and 7 then w - 4 else 1 end;
    for d in select jsonb_object_keys(p_tpl -> ph) loop
      i := 0;
      for r in select * from jsonb_array_elements(p_tpl -> ph -> d) loop
        i := i + 1;
        n := (r->>1)::int;
        n := case when half then greatest(1, ceil(n / 2.0)::int) when (r->>4)::boolean then greatest(n, least(6, n + wp - 1)) else n end;
        update public.program_exercises
        set exercise_id = (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1),
            exercise_name = r->>0, sets = n, reps = r->>2, rest_seconds = (r->>3)::smallint, kind = 'exercise'
        where program_id = prog and week_number = w and day_number = d::smallint and sort_order = i;
        if not found then
          insert into public.program_exercises (program_id, week_number, day_number, sort_order, exercise_id, exercise_name, sets, reps, rest_seconds, kind)
          values (prog, w, d::smallint, i,
            (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1),
            r->>0, n, r->>2, (r->>3)::smallint, 'exercise');
        end if;
      end loop;
      if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.week_number = w
                 and pe.day_number = d::smallint and pe.sort_order > i) then
        raise exception '% week % day % has more rows than the template', p_name, w, d;
      end if;
    end loop;
  end loop;
  if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.exercise_id is null) then
    raise exception 'an exercise in % is not in the library', p_name;
  end if;
end $f$;

-- Applied through the Supabase connector one sport at a time, so the helper
-- is a lasting function (the connector refuses DROP); only the database owner
-- can run it.
revoke execute on function public.add_offseason_program(text, text, text, text, jsonb, jsonb) from public, anon, authenticated;

do $$
declare
  nutrition text := 'The off-season is when you build: eat enough to recover and add muscle. Protein 1.6-2.2 g per kg of bodyweight a day, split over 4-5 meals (chicken, beef, fish, eggs, maas, yoghurt, beans). Carbs of 4-6 g/kg on hard training days from rice, potatoes, sweet potato, pap, bread and fruit, and a bit less on rest days. Eat a carb-and-protein meal 2-3 hours before training and another within 2 hours after. Drink 35-40 ml of water per kg a day plus 500-750 ml per hour of training. On long rides, take 30-60 g of carbs an hour. Sleep 8-9 hours: it''s when you get stronger.';
  warm_up text := 'RAMP warm-up, 10 minutes: 3-4 minutes easy jog, skipping or bike, then leg swings, hip circles, world''s greatest stretch and band pull-aparts, then 2-3 short, fast efforts such as skips, jumps or strides. Before the first lift, do 2-3 lighter ramp-up sets.';
begin
  perform public.add_offseason_program('Off-Season – Soccer', 'For Soccer (football): an 8-week off-season program. It builds leg strength and hamstrings that hold up to sprinting (Nordic curls), strong hips and groin for kicking and cutting, a big aerobic engine, and the repeated-sprint speed to keep going hard for 90 minutes. Each week has 2 strength sessions (Monday lower body plus a row, Thursday upper body plus hips, so every muscle is trained twice a week), 1 conditioning session (Tuesday), 1 speed and power session (Friday) and 1 easy recovery session (Wednesday: zone 2 cardio and mobility). Saturday is for playing your sport or resting, Sunday is full rest. Weeks 1-3 build strength and fitness (sets go up each week), week 4 is a recovery week at half the sets, weeks 5-7 turn that strength into power and sport-specific fitness, and week 8 is a test week at half the sets: test your best clean set on the main lifts, a broad jump and a 20 m sprint, then you''re ready for pre-season. No set goes to failure: stop each set with 1-2 good reps left. In weeks 1-3 sprint at 9/10, then all-out from week 5.',
    nutrition, warm_up, '{"1": "Strength A: lower body", "2": "Conditioning", "3": "Active recovery: zone 2 + mobility", "4": "Strength B: upper body & hips", "5": "Speed & power", "6": "Play your sport or rest", "7": "Full rest"}'::jsonb,
    '{"p1":{"1":[["Trap Bar Deadlift",3,"5-6",150,true],["Dumbbell Bulgarian Split Squat",3,"8 each leg",90,false],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Hip Adduction",3,"12",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pallof Press",3,"10 each side",45,false],["Inverted Row",3,"8-12",60,false]],"2":[["Running Intervals",3,"4 min at 8/10, 3 min easy jog between",180,true],["Plank",3,"40 sec",30,false]],"4":[["Pull-Up",3,"6-8",120,true],["Flat Dumbbell Press",3,"8-10",90,false],["Hip Thrust",3,"8-10",90,false],["Dumbbell Single-Arm Row",3,"10 each arm",60,false],["Push-Up",2,"12-15",60,false],["Cable Wood Chopper",3,"10 each side",45,false]],"5":[["A-Skip",2,"20 m",60,false],["Acceleration Sprint",5,"20 m fast (9/10), walk back",120,true],["Pro Agility Shuttle",4,"1 fast (9/10)",120,false],["Broad Jump",3,"5, stick the landing",90,false],["Lateral Bound",3,"5 each side, stick it",60,false],["Single-Leg Hop",2,"5 each leg",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]]},"p2":{"1":[["Trap Bar Deadlift",4,"3-5",180,false],["Box Jump",4,"3, straight after each deadlift set",120,false],["Barbell Split Squat",3,"5-6 each leg",120,false],["Nordic Hamstring Curl",2,"4-5, slow on the way down",120,false],["Hip Adduction",3,"12",60,false],["Single-Leg Standing Calf Raise",3,"10 each leg, fast up",45,false],["Inverted Row",3,"8-10, feet raised",60,false]],"2":[["Running Intervals",3,"6 x 30 m sprints with 20 sec between. 3 min between sets",180,false],["Tempo Run",1,"8 x 100 m at 70%, walk 30 sec between",60,false]],"4":[["Weighted Pull-Up",4,"4-6",150,true],["Bench Press",4,"4-6",150,false],["Hip Thrust",3,"6, fast up",120,false],["Chest-Supported Row",3,"8",90,false],["Medicine Ball Chest Pass",3,"6 fast",60,false],["Medicine Ball Rotational Throw",3,"5 each side",60,false],["Pallof Press",3,"10 each side",45,false]],"5":[["Wall Drive Drill",2,"3 x 5 sec fast",60,false],["Flying Sprint",4,"20 m fast after a 20 m build-up",180,true],["Pro Agility Shuttle",4,"1 all-out",120,false],["Depth Jump",3,"4, from a low box (30-40 cm): step off, land and jump straight up",120,false],["Bounding",3,"30 m",90,false],["Lateral Bound",3,"5 each side",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]]}}'::jsonb);
  perform public.add_offseason_program('Off-Season – Rugby', 'For Rugby: an 8-week off-season program. It builds the strength and size for contact, a strong neck and upper back, powerful hips for scrums, rucks and tackles, speed off the mark, and the fitness to repeat hard efforts with little rest. Each week has 2 strength sessions (Monday lower body plus a row, Thursday upper body plus hips, so every muscle is trained twice a week), 1 conditioning session (Tuesday), 1 speed and power session (Friday) and 1 easy recovery session (Wednesday: zone 2 cardio and mobility). Saturday is for playing your sport or resting, Sunday is full rest. Weeks 1-3 build strength and fitness (sets go up each week), week 4 is a recovery week at half the sets, weeks 5-7 turn that strength into power and sport-specific fitness, and week 8 is a test week at half the sets: test your best clean set on the main lifts, a broad jump and a 20 m sprint, then you''re ready for pre-season. No set goes to failure: stop each set with 1-2 good reps left. In weeks 1-3 sprint at 9/10, then all-out from week 5.',
